const B=globalThis.BABYLON;
export const palette={ivory:'#e8e4d3',white:'#f8f4e6',cream:'#cfceb9',orange:'#da6637',darkOrange:'#a33c24',dark:'#233b40',black:'#19292f',metal:'#8c9da0',lightMetal:'#c1cbc7',glass:'#4b8d9d',glassLight:'#7baaad',rubber:'#202a2b',red:'#ff4939',green:'#78e599',yellow:'#e9e37d',jet:'#d7ded7',blue:'#345b65'};
export class VoxelPart{
 constructor(name,scene,parent,size=.08,origin=[0,0,0]){this.name=name;this.scene=scene;this.size=size;this.cells=new Map();this.node=new B.TransformNode(name,scene);this.node.parent=parent;this.node.position.set(...origin);this.count=0;}
 set(x,y,z,color){this.cells.set(`${x},${y},${z}`,{x,y,z,color});}
 box(cx,cy,cz,sx,sy,sz,color){const s=this.size;for(let x=Math.ceil((cx-sx/2)/s);x<(cx+sx/2)/s;x++)for(let y=Math.ceil((cy-sy/2)/s);y<(cy+sy/2)/s;y++)for(let z=Math.ceil((cz-sz/2)/s);z<(cz+sz/2)/s;z++)this.set(x,y,z,color);return this;}
 volume(bounds,fn){const s=this.size;for(let x=Math.ceil(bounds[0]/s);x<=bounds[1]/s;x++)for(let y=Math.ceil(bounds[2]/s);y<=bounds[3]/s;y++)for(let z=Math.ceil(bounds[4]/s);z<=bounds[5]/s;z++){const c=fn(x*s,y*s,z*s);if(c)this.set(x,y,z,c);}return this;}
 rod(a,b,r,color){const s=this.size;const d=b.map((v,i)=>v-a[i]),l=d.reduce((t,v)=>t+v*v,0);return this.volume([Math.min(a[0],b[0])-r,Math.max(a[0],b[0])+r,Math.min(a[1],b[1])-r,Math.max(a[1],b[1])+r,Math.min(a[2],b[2])-r,Math.max(a[2],b[2])+r],(x,y,z)=>{const p=[x-a[0],y-a[1],z-a[2]],t=Math.max(0,Math.min(1,p.reduce((v,n,i)=>v+n*d[i],0)/l));return p.reduce((v,n,i)=>v+(n-d[i]*t)**2,0)<r*r?color:null;});}
 build(keepCells=false){const positions=[],normals=[],colors=[],indices=[],s=this.size,h=s*.5;const faces=[[[1,0,0],[[h,-h,-h],[h,h,-h],[h,h,h],[h,-h,h]]],[[-1,0,0],[[-h,-h,h],[-h,h,h],[-h,h,-h],[-h,-h,-h]]],[[0,1,0],[[-h,h,-h],[-h,h,h],[h,h,h],[h,h,-h]]],[[0,-1,0],[[-h,-h,h],[-h,-h,-h],[h,-h,-h],[h,-h,h]]],[[0,0,1],[[h,-h,h],[h,h,h],[-h,h,h],[-h,-h,h]]],[[0,0,-1],[[-h,-h,-h],[-h,h,-h],[h,h,-h],[h,-h,-h]]]];const cache={};
 for(const cell of this.cells.values()){const{x,y,z,color}=cell;let col=cache[color];if(!col)col=cache[color]=B.Color3.FromHexString(palette[color]||color);const hash=Math.sin(x*13.91+y*77.13+z*39.71)*43758.55;const shade=.91+(hash-Math.floor(hash))*.13;for(const[n,vs]of faces){if(this.cells.has(`${x+n[0]},${y+n[1]},${z+n[2]}`))continue;const id=positions.length/3;for(const v of vs){positions.push(x*s+v[0],y*s+v[1],z*s+v[2]);normals.push(...n);colors.push(col.r*shade,col.g*shade,col.b*shade,1);}indices.push(id,id+1,id+2,id,id+2,id+3);}}
 const mesh=new B.Mesh(this.name+' voxels',this.scene),data=new B.VertexData();data.positions=positions;data.normals=normals;data.colors=colors;data.indices=indices;data.applyToMesh(mesh);mesh.parent=this.node;mesh.material=this.scene.voxelMaterial;mesh.isPickable=false;mesh.useVertexColors=true;mesh.receiveShadows=true;this.mesh=mesh;this.count=this.cells.size;if(keepCells)mesh.metadata={voxelSize:s,voxelCells:Array.from(this.cells.values())};this.cells.clear();return this;}
}
export function initMaterials(scene){const mat=new B.StandardMaterial('painted voxel alloy',scene);mat.diffuseColor=B.Color3.White();mat.specularColor=new B.Color3(.17,.2,.19);mat.specularPower=48;mat.backFaceCulling=false;scene.voxelMaterial=mat;return mat;}
